"""Full literal, bounded Unit18 verbal matrices. Never writes active registers."""
import json,copy
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];O=Path(__file__).resolve().parent
L={x['lemma_id']:x for x in json.load(open(ROOT/'lexicon/entries.json',encoding='utf8'))['lemmas']}
S=[]
def norm(a):
 if not isinstance(a,dict):return {}
 a=copy.deepcopy(a)
 for k in ['use','function','citation_notation']:a.pop(k,None)
 if a.get('number') in ['singular','plural']:a['number']={'singular':'sg','plural':'pl'}[a['number']]
 return a
def cell(lemma,form,a,suffix):
 matches=[f for f in L.get(lemma,{}).get('forms',[])if f['form']==form and norm(f['analysis'])==norm(a)]
 old=next((f for f in matches if f.get('production_taught_in')),None)
 return {'lemma_id':lemma,'form_id':old['form_id'] if old else f'{lemma}-u18-{suffix}','form':form,'analysis':a,'knowledge_status':'previously_taught' if old else 'new_production','prior_record':copy.deepcopy(old),'evidence_basis':'Literal application of the separately recorded source-checked stem and ending rules; scope does not imply other finite systems or syntactic uses.','proposed_teaching_id':f'NEW-U18-VERB-{lemma.upper()}'}
def add(lemma,head,scope,ev,rules,items,gloss=None,pr=None,pt=None,sub=None,imp=None,infs=None,parts=None):
 s={'system_id':f'u18-{lemma}-{scope}','lemma_id':lemma,'headword':head,'scope':scope,'origin_category':'new teaching material derived from specified primary rules','evidence_refs':ev,'derivation_rules':rules,'source_items':items,'cells':[],'prior_senses':copy.deepcopy(L.get(lemma,{}).get('senses',[])),'display_route':f'NEW-U18-VERB-{lemma.upper()}','teaching_scope':'All literal cells in this defined system are displayed and taught for production. Ordinary uses are limited to the explicitly assigned sense and construction records; citation entries outside these cells are supplied reference only.'}
 if gloss:s['sense_proposal']={'sense_id':f'{lemma}-u18-selected','gloss':gloss,'knowledge_status':'new_production','scope':'Only elementary frames explicitly stated in the Unit18 construction audit.'}
 for tense,vs in [('present',pr),('preterite',pt)]:
  if vs:
   assert len(vs)==6
   for i,v in enumerate(vs):
    p=i%3+1;n='sg' if i<3 else 'pl';s['cells'].append(cell(lemma,v,{'tense':tense,'mood':'indicative','person':p,'number':n},f'{tense}-indicative-{p}-{n}'))
 for tense,vs in (sub or {}).items():
  assert len(vs)==2
  for n,v in zip(['sg','pl'],vs):
   for p in [1,2,3]:s['cells'].append(cell(lemma,v,{'tense':tense,'mood':'subjunctive','person':p,'number':n},f'{tense}-subjunctive-{p}-{n}'))
 if imp:
  for n,v in zip(['sg','pl'],imp):s['cells'].append(cell(lemma,v,{'mood':'imperative','person':2,'number':n},f'imperative-2-{n}'))
 if infs:
  for typ,v in zip(['plain','inflected'],infs):s['cells'].append(cell(lemma,v,{'verb_form':typ+'_infinitive'},typ+'-infinitive'))
 if parts:
  for t,v in zip(['present','past'],parts):s['cells'].append(cell(lemma,v,{'verb_form':'participle','tense':t,'agreement':'base'},t+'-participle'))
 s['display_cell_count']=len(s['cells']);s['productive_cell_count']=sum(c['knowledge_status']=='new_production'for c in s['cells']);S.append(s);return s
def six(a,b,c,d):return [a,b,c,d,d,d]
add('bethurfan','beðurfan','indicative12',['U18G-BT95','U18G-FB77'],['Prefixed preterite-present: present singular beðearf, beðearft, beðearf; plural beðurfon. Dental preterite beðorfte/-st/-on, no invented weak present *beðurfað.','BT95 expressly supplies singular/plural present and preterite stems and the exact Genesis43.4,8 relative-clause parallel. No productive infinitive or subjunctive is assigned merely because BT lists it.'],['44.3','44.6'],'need; require',pr=six('beðearf','beðearft','beðearf','beðurfon'),pt=six('beðorfte','beðorftest','beðorfte','beðorfton'))
add('oncnawan','oncnāwan','indicative12',['U18G-EX59','U18G-FB66','U18G-FB67','U18G-FB55','U18G-FB17'],['Cook109 cnāwan gives cnēow/cnēowon; present ā changes to ǣ in2/3sg under17,94. Prefix on- belongs to this lexical verb.','Past2sg uses cnēow- plus-e, not the past1/3sg bare stem. Accusative person recognized.'],['46.4'],'recognize; know by recognition',pr=six('oncnāwe','oncnǣwst','oncnǣwð','oncnāwað'),pt=six('oncnēow','oncnēowe','oncnēow','oncnēowon'))
add('undon','undōn','indicative12',['U18G-EX30','U18G-FB79','U18G-FB80'],['Anomalous dōn system with lexical un-: dō/dēst/dēð/dōð; preterite dyde/dydest/dydon. Keep ū absent from prefix un-.','Undo/open an accusative tied container. No automatic extension to every figurative English undo sense.'],['45.8'],'undo; open',pr=six('undō','undēst','undēð','undōð'),pt=six('undyde','undydest','undyde','undydon'))
add('lecgean','lęcgean','indicative12',['U18G-EX31','U18G-FB71','U18G-FB72','U18G-FB176'],['Short weakI j-present: lęcge, lęgest, lęgeð; selected -ean spelling gives lęcgeað in present plural. Remove doubled/geminate representation in2/3sg, retain full short-stem endings.','Select explicitly attested uncontracted lęgde/lęgdon, not source variant lēde/lēdon. Present -cg- alternates with preterite -g-; no *lęcgde. Reading lęcgeað is an imperative and remains separately supplied because only indicative12 is newly productive.'],['46.3'],'lay; place',pr=six('lęcge','lęgest','lęgeð','lęcgeað'),pt=six('lęgde','lęgdest','lęgde','lęgdon'))
add('foresecgean','foresęcgean','indicative12',['U18G-EX31','U18G-FB75','U18G-BTS240'],['Prefix fore- plus Cook123 sęcg(e)an. Select -ean/-eað; present2/3sg foresægst/foresægð and preterite foresægde/-st/-on.','Uncontracted æ before gd stays unmarked as Cook prints sægde; contracted sāde is a separate documented alternative, not a license to lengthen *sǣgde.','BT Supplement240 explicitly distinguishes having mentioned someone earlier from future prediction. Here use the past-reference sense with accusative person/topic and dative hearer.'],['46.6'],'mention before; tell of beforehand',pr=six('foresęcge','foresægst','foresægð','foresęcgeað'),pt=six('foresægde','foresægdest','foresægde','foresægdon'))
add('forstelan','forstelan','indicative12',['U18G-EX31','U18G-FB63','U18G-FB55'],['StrongIV stelan: e/æ/ǣ/o. Present2/3sg i; select forstilst/forstilð. Past singular1/3 forstæl,2sg forstǣle,plural forstǣlon.','For- is lexical in47.1/47.8; unprefixed stelan in47.2 remains a distinct lemma. No newly productive past participle is inferred.'],['47.1','47.8'],'steal away; steal',pr=six('forstele','forstilst','forstilð','forstelað'),pt=six('forstæl','forstǣle','forstæl','forstǣlon'))
add('ceapian','cēapian','indicative12-infinitive2',['U18G-EX30','U18G-FB73','U18G-FB74','U18G-FB106'],['WeakII cēap-: present-ie/-ast/-að/-iað; past-ode/-odest/-odon. Preserve marked ēa in every stem.','Plain cēapian and inflected cēapianne form a complete infinitive pair. Inflected purpose use with stranded instrument mid in45.9 is supplied as a whole frame, not inferred from the paradigm.'],['45.8','45.9'],'trade; traffic; buy through trade',pr=six('cēapie','cēapast','cēapað','cēapiað'),pt=six('cēapode','cēapodest','cēapode','cēapodon'),infs=['cēapian','cēapianne'])
for lemma,head,pair,ev,gloss,items,rules in [
 ('gedon','gedōn',['gedō','gedōn'],['U18G-EX30','U18G-FB79','U18G-FB80'],'make; cause to be',['45.2'],['Anomalous present subjunctive dō/dōn with lexical ge-. In45.2 accusative person plus agreeing adjective gives make him gracious.']),
 ('agiefan','āgiefan',['āgiefe','āgiefen'],['U18G-EX30','U18G-FB63','U18G-FB64','U18G-FB55'],'give back; restore',['45.2'],['StrongV present subjunctive on unchanged present stem gief-; retain lexical ā-. Dative recipient plus accusative returned person.']),
 ('hlystan','hlystan',['hlyste','hlysten'],['U18G-EX30','U18G-FB68','U18G-FB72','U18G-FB156'],'listen to; heed',['45.7'],['Long-stem weakI present subjunctive hlyst-e/-en. Genitive speech/content heard; no productive indicative implied.']),
 ('theowian','ðēowian',['ðēowie','ðēowien'],['U18G-BT1056','U18G-FB73','U18G-FB74'],'enslave; reduce to servitude',['45.6'],['WeakII subjunctive -ie/-ien. BT1056 senseII gives direct Gen43.18 accusative-person enslave construction. The common serve sense is separate and is not assigned. Source -ige is a documented -ie variant under Cook119, not a different mood.']),
 ('bereafian','berēafian',['berēafie','berēafien'],['U18G-EX44','U18G-FB73','U18G-FB74','U18G-BTS81'],'despoil; deprive of',['45.2','45.6'],['WeakII present subjunctive -ie/-ien; accusative deprived person plus genitive possession. Past passive independently uses the base participle below.']),
 ('gemiltsian','gemiltsian',['gemiltsie','gemiltsien'],['U18G-EX31','U18G-FB73','U18G-FB74'],None,['46.6'],['Extend only present subjunctive of the already taught weakII verb; preserve prior dative-person pity frame.']),
 ('geseon','gesēon',['gesēo','gesēon'],['U18G-FB64','U18G-FB55'],None,['47.11','48.3'],['Contracted sēon present subjunctive sēo/sēon with lexical ge-. No tenses besides these6 cells newly assigned.']),
 ('wunian','wunian',['wunie','wunien'],['U18G-FB73','U18G-FB74'],None,['48.8'],['WeakII present subjunctive -ie/-ien. Earlier indicative teaching did not supply this mood. Dwell + on/dative place remains the ordinary frame.'])]:add(lemma,head,'present-subjunctive6',ev,rules,items,gloss,sub={'present':pair})
add('bringan','bringan','subjunctive12',['U18G-FB70','U18G-FB72','U18G-FB55'],['WeakI irregular dental preterite brōhte: g changes to h before the dental group; present bringe/bringen, past brōhte/brōhten.','Both tenses displayed for all3persons and both numbers. Present clauses44.2/6,47.11 and the past oath48.1 are independently explained.'],['44.2','44.6','47.11','48.1'],sub={'present':['bringe','bringen'],'preterite':['brōhte','brōhten']})
add('laedan','lǣdan','preterite-subjunctive6',['U18G-FB68','U18G-FB69','U18G-FB72'],['WeakI d-stem: preterite dental coalesces to dd; lǣdde/lǣdden in all persons. Select past subjunctive under reported desire, not a new present mood.'],['44.5'],sub={'preterite':['lǣdde','lǣdden']})
add('stelan','stelan','preterite-subjunctive6',['U18G-EX31','U18G-FB63','U18G-FB55'],['StrongIV: preterite subjunctive uses plural stem stǣl- in both numbers, stǣle/stǣlen. It refers to questioned anterior theft in47.2; do not read it as present wish merely from English om.have.'],['47.2'],'steal',sub={'preterite':['stǣle','stǣlen']})
for lemma,head,pair,items in [('gearcian','gearcian',['gearca','gearciað'],['45.4']),('ascian','āscian',['āsca','āsciað'],['46.9'])]:add(lemma,head,'imperative2',['U18G-FB73','U18G-FB74'],['Complete weakII singular/plural command pair -a/-iað. Earlier indicative scope is preserved; no unlisted mood follows.'],items,imp=pair)
for lemma,head,pair,ev,gloss,items in [
 ('diernan','diernan',['diernan','diernanne'],['U18G-EX32','U18G-FB68','U18G-FB106'],'conceal; hide',['48.4']),
 ('erian','ęrian',['ęrian','ęrianne'],['U18G-EX33','U18G-FB71','U18G-FB106'],'plow',['48.7']),
 ('ripan','rīpan',['rīpan','rīpanne'],['U18G-EX33','U18G-FB59','U18G-FB106'],'reap',['48.7']),
 ('giernan','giernan',['giernan','giernanne'],['U18G-EX29','U18G-FB68','U18G-FB106'],None,['44.5'])]:add(lemma,head,'infinitive2',ev,['Complete plain/inflected infinitive pair. Select -anne/-ianne as already established; -enne variants remain valid source alternatives but are not the selected recall spelling.','Only plain modal infinitive or stated lexical complement uses are assigned; inflected display alone teaches no unrestricted gerund syntax.'],items,gloss,infs=pair)
for lemma,head,pair,ev,gloss,items,rules in [
 ('afaeran','āfǣran',['āfǣrende','āfǣred'],['U18G-EX48','U18G-FB68','U18G-FB69','U18G-FB41'],'frighten',['45.6'],['Ex48 explicitly prints āfǣran, not āfīran. Long weakI gives present -ende, uncontracted past -ed. Base past predicate may remain uninflected with plural subject under62.']),
 ('beodan','bēodan',['bēodende','boden'],['U18G-FB60','U18G-FB55'],None,['45.5','47.2'],['StrongII eo/ea/u/o: present bēodende, past boden. Prior citation did not assign the past participle for production. Impersonal command passive is independently supplied whole.']),
 ('bereafian','berēafian',['berēafiende','berēafod'],['U18G-EX44','U18G-BTS81','U18G-FB73','U18G-FB74'],None,['45.2','45.6'],['WeakII complete base pair -iende/-od. Preserve long ēa. The genitive deprivation complement is taught separately.']),
 ('ofslean','ofslēan',['ofslēande','ofslægen'],['U18G-EX32','U18G-FB65','U18G-FB55'], 'slay; kill',['47.3'],['Contracted VI slēan gives present slēande, past slægen (Cook107 also permits slagen). Retain lexical of-. No new complete finite system is implied.'])]:add(lemma,head,'participle2',ev,rules,items,gloss,parts=pair)
s={'system_id':'u18-ofthyncean-impersonal4','lemma_id':'ofthyncean','headword':'ofðyncean','scope':'impersonal third-singular indicative/subjunctive, present and preterite','origin_category':'new teaching material derived from specified primary rules','evidence_refs':['U18G-EX49','U18G-FB70','U18G-FB102'],'derivation_rules':['Cook114 ðync(e)an has weak preterite ðūhte; prefix of- is lexical in Ex49 grieve. Selected present syncopated indicative ofðyncð, subjunctive ofðynce; both past moods ofðūhte.','The four cells exhaust this deliberately bounded third-singular impersonal system. A dative experiencer is not a nominative subject and does not trigger personal/plural agreement. A cause clause fills the impersonal subject position under190. No unrestricted personal conjugation is introduced.'],'source_items':['48.6'],'cells':[],'display_route':'NEW-U18-VERB-OFTHYNCEAN','teaching_scope':'Complete four-cell impersonal statement/wish contrast in both tenses, with visible clause-frame explanation.','sense_proposal':{'sense_id':'ofthyncean-u18-selected','gloss':'grieve; displease (impersonal)','knowledge_status':'new_production','scope':'Dative experiencer plus cause/content clause only.'},'prior_senses':copy.deepcopy(L.get('ofthyncean',{}).get('senses',[]))}
for t,m,v in [('present','indicative','ofðyncð'),('present','subjunctive','ofðynce'),('preterite','indicative','ofðūhte'),('preterite','subjunctive','ofðūhte')]:s['cells'].append(cell('ofthyncean',v,{'tense':t,'mood':m,'person':3,'number':'sg','construction':'impersonal'},f'{t}-{m}-3-sg-impersonal'))
s['display_cell_count']=4;s['productive_cell_count']=sum(c['knowledge_status']=='new_production'for c in s['cells']);S.append(s)
D={'schema_version':1,'status':'precontract linguistic proposal; coordinator reconciliation and independent paradigm review required','baseline':'0eda277','access':'author-only morphology audit, not lesson/key prose','systems':S,'reference_only':[],'counts':{'systems':len(S),'display_cells':sum(len(s['cells'])for s in S),'new_production_cell_appearances':sum(s['productive_cell_count']for s in S),'unique_form_ids':len({c['form_id']for s in S for c in s['cells']})}}
(O/'verbal-systems.json').write_text(json.dumps(D,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print(D['counts'])
